const payload = $input.first().json;
const data = payload.data || payload;

if (!data || !data.key) {
  return [];
}

// 1. Filter out bot messages
if (data.key.fromMe === true) {
  return [];
}

// 2. Filter out groups
const remoteJid = data.key.remoteJid || '';
if (remoteJid.includes('@g.us') || remoteJid.includes('@broadcast')) {
  return [];
}

// 3. Extract phone and text
const cleanPhone = remoteJid.replace('@s.whatsapp.net', '').replace(/[^0-9]/g, '');
const msgObj = data.message || {};
let text = '';
if (msgObj.conversation) text = msgObj.conversation;
else if (msgObj.extendedTextMessage && msgObj.extendedTextMessage.text) text = msgObj.extendedTextMessage.text;

text = (text || '').trim();
if (!text) return [];

const customerName = data.pushName || 'PRIMETEK Store Visitor';

return [{
  json: {
    customerPhone: cleanPhone,
    customerName: customerName,
    customerMessage: text,
    timestamp: data.messageTimestamp || Math.floor(Date.now() / 1000),
    storeInstance: payload.instance || 'primetek_store'
  }
}];
